export function loss(teacher:number[],student:number[]){if(student.some(p=>p<=0))throw new Error("Positive student probabilities");const terms=teacher.map((p,i)=>-p*Math.log(student[i]));return {terms,total:terms.reduce((a,b)=>a+b,0)};}export function run(mode:number){const teacher=mode===1?[1,0,0]:[.6,.3,.1],students=[[.6,.2,.2],[.6,.35,.05]],soft=students.map(v=>loss(teacher,v)),hard=students.map(v=>loss([1,0,0],v));return {teacher,students,soft,hard};}

function Picture({mode}:{mode:number}){const r=m.run(mode);return <svg className={s.plot} viewBox="0 0 280 112" role="img" aria-label="Same top class, different loss — worked example"><text x="5" y="17">teacher [{r.teacher.join(',')}]</text>{r.students.map((row,i)=><g key={i}><text x="5" y={39+i*42}>{i===0?'A':'B'} [{row.join(',')}]</text><text x="187" y={39+i*42}>L={f(r.soft[i].total,3)}</text><text x="22" y={57+i*42}>{r.soft[i].terms.map(v=>f(v,3)).join(' + ')}</text></g>)}</svg>;}

Locked inputs: Teacher [.6,.3,.1]; students A [.6,.2,.2], B [.6,.35,.05]. Natural-log cross-entropy; temperature 1.
